describe('profile image cleanup', () => {
	const folder = path.join(nconf.get('upload_path'), 'profile');

	async function createImages(uid, type) {
		await fs.promises.mkdir(folder, { recursive: true });
		const names = [
			`${uid}-profile${type}.png`,
			`${uid}-profile${type}.jpeg`,
			`${uid}-profile${type}-123.jpg`,
			`${uid}-profile${type}-456.bmp`,
		];
		const paths = names.map(name => path.join(folder, name));
		await Promise.all(paths.map(imagePath => fs.promises.writeFile(imagePath, 'image')));
		return paths;
	}

	it('should remove every local cover variant and clear its fields', async () => {
		const uid = await User.create({ username: 'covercleanupuser' });
		const paths = await createImages(uid, 'cover');
		const url = `${nconf.get('relative_path')}/assets/uploads/profile/${path.basename(paths[2])}`;
		await User.setUserFields(uid, { 'cover:url': url, 'cover:position': '50% 50%' });
		assert(paths.includes(await User.getLocalCoverPath(uid)));

		const result = await User.removeCoverPicture(uid);
		assert(result && typeof result === 'object');
		const fields = await User.getUserFields(uid, ['cover:url', 'cover:position']);
		assert(!fields['cover:url']);
		assert(!fields['cover:position']);
		assert(paths.every(imagePath => !fs.existsSync(imagePath)));
